/** Translate the source taxonomy without changing resource identifiers or product names. */
export function localizedCategory(category: string, locale: Locale): string {
  const value = category.trim();
  const column = LOCALES.indexOf(locale);
  const key = value.toLowerCase();
  const direct = categoryTranslations.get(categoryAliases[key] ?? key);
  if (direct) return direct[column];
  const colon = value.indexOf(':');
  if (colon >= 0) {
    const prefixKey = value.slice(0, colon).trim().toLowerCase();
    const prefix = prefixTranslations.get(prefixKey);
    if (prefix) {
      const suffix = value.slice(colon + 1).trim();
      // These prefixes name specific games, engines, platforms, or security products.
      // In particular, the Source engine must not become the generic "source code" label.
      return `${prefix[column]}: ${prefixKey === 'detection' ? localizedCategory(suffix, locale) : suffix}`;
    }
  }
  const separator = value.match(/\s+(?:\/|>|›)\s+/);
  if (separator && separator.index !== undefined) {
    const left = value.slice(0, separator.index);
    const right = value.slice(separator.index + separator[0].length);
    return `${localizedCategory(left, locale)} › ${localizedCategory(right, locale)}`;
  }
  const plugins = value.match(/^(.+) Plugins$/i);
  if (plugins) return `${plugins[1]} · ${categoryTranslations.get('plugins')![column]}`;
  return value;
}

/** Known taxonomy labels are translated; technology and project names retain their spelling. */
export function localizedTag(tag: string, locale: Locale): string {
  const d = getDictionary(locale);
  const labels: Record<string, string> = {
    tool: d.tools, tools: d.tools, guide: d.guides, guides: d.guides,
    reference: d.references, references: d.references, library: d.libraries, libraries: d.libraries,
    collection: d.collections, collections: d.collections, beginner: d.beginner,
    intermediate: d.intermediate, advanced: d.advanced, all: d.allLevelsLabel,
  };
  return labels[tag.toLowerCase()] ?? localizedCategory(tag, locale);
}
